//go:build amd64

package floats

// The AVX2 kernels of the MDCT fold and unfold (fold.go), generated by go-asmgen
// (fold_amd64_gen.go) into fold_amd64.s: four float64 per step, for a CPU with the
// AVX2+FMA of the other kernels (hasAVX2FMA, kernels_amd64.go; no FMA instruction
// is used); the portable loops otherwise. A kernel does the floor(h/4) steps that
// fit and the Go code finishes the rest. No kernel keeps a pointer: go:noescape.
//
//go:noescape
func mdctFold64AVX2(dst, x []float64)

//go:noescape
func mdctFoldFrom32AVX2(dst []float64, x []float32)

//go:noescape
func mdctUnfold64AVX2(dst, u []float64)

//go:noescape
func mdctUnfoldTo32AVX2(dst []float32, u []float64)

func mdctFold(dst, x []float64) {
	if !hasAVX2FMA {
		foldTail(dst, x, 0)
		return
	}
	mdctFold64AVX2(dst, x)
	foldTail(dst, x, (len(x)/4)&^3)
}

func mdctFold32(dst []float64, x []float32) {
	if !hasAVX2FMA {
		fold32Tail(dst, x, 0)
		return
	}
	mdctFoldFrom32AVX2(dst, x)
	fold32Tail(dst, x, (len(x)/4)&^3)
}

func mdctUnfold(dst, u []float64) {
	if !hasAVX2FMA {
		unfoldTail(dst, u, 0)
		return
	}
	mdctUnfold64AVX2(dst, u)
	unfoldTail(dst, u, (len(u)/2)&^3)
}

func mdctUnfold32(dst []float32, u []float64) {
	if !hasAVX2FMA {
		unfold32Tail(dst, u, 0)
		return
	}
	mdctUnfoldTo32AVX2(dst, u)
	unfold32Tail(dst, u, (len(u)/2)&^3)
}
